import{z as o,x as B,o as t,c as p,q as A,j as r,D as l,d as E,s as i,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"异步检查点","description":"","frontmatter":{"title":"异步检查点","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/async-checkpointing.md","filePath":"llm/async-checkpointing.md","lastUpdated":1791413859000}'),d={name:"llm/async-checkpointing.md"};function m(h,a,c,D,u,C){const n=B("Mermaid");return t(),p("div",null,[a[2]||(a[2]=A('<h1 id="异步检查点" tabindex="-1">异步检查点 <a class="header-anchor" href="#异步检查点" aria-label="Permalink to &quot;异步检查点&quot;">​</a></h1><div class="epigraph"><p>把参数与优化器状态的快照提交给后台线程写盘，训练流继续算下一个微批；检查点的墙钟不应等于一次完整的同步保存。</p><footer>—— Mohan 等，CheckFreq；对照 Meta / NVIDIA 预训练中的异步保存实践</footer></div><p><a href="/llm/moe-training-all2all">上一课</a>把稳态的 All-to-All 税付清。万卡上下一步不是更快的 GEMM，而是：多久必须落盘一次，才能在掉卡后只丢掉可接受的 token。同步保存会让整张集群等最慢的磁盘。本课不重讲专家置换。缺口是把保存从训练关键路径上挪走——异步检查点——以及它与 1F1B 在飞状态、DualPipe 双流之间的一致性约束。下一课谈落盘格式如何跨并行拓扑重切。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><span class="marginnote">「优化器状态」指 Adam 里与参数同形状的两份数组：一阶矩 m 与二阶矩 v。落盘体积至少是参数的 3 倍（参数 + m + v），混合精度训练还要另存 FP32 主权重，实际可到 4 倍以上。所以「检查点就存个参数量」是最常见的体积低估。</span></p><p>检查点体积随 \\(\\Phi\\) 与优化器状态（Adam 两份矩）线性涨，MoE 更按专家数涨。同步 <code>save</code> 的时间可到数分钟，MegaScale 一类报告里故障间隔若也是这个量级，有效算力被保存吃掉。CheckFreq 把「多频繁地检查」做成系统问题：太稀则故障丢失大；太密则保存干扰训练。异步的意思是：训练线程拷一份（或用双缓冲）给 writer，writer 用独立流或 CPU 把分片写到并行文件系统。</p><p>危险是写的过程中参数还在变。必须在全局 batch 边界、优化器 step 之后取一致快照，而不是在 1F1B 稳态的半拍上取。DualPipe 双流、ZB 未完成的 \\(W\\)，都不允许作为快照点。</p><h3 id="拷贝本身也可以很贵" tabindex="-1">拷贝本身也可以很贵 <a class="header-anchor" href="#拷贝本身也可以很贵" aria-label="Permalink to &quot;拷贝本身也可以很贵&quot;">​</a></h3><p>GPU→CPU 或 GPU→GPU 暂存若走同步 memcpy，只是把停顿换了个名字。需要 pinned memory、流水化拷贝、或 GPU 侧的快照缓冲与计算双缓冲轮换。Mohan 等人讨论在不扰动训练节奏的前提下提高检查频率。</p><p><span class="marginnote">双缓冲可以想成餐厅的备菜台：厨师（训练线程）只往新托盘里放菜，服务员（writer 线程）慢慢端走旧托盘，两套托盘轮换。没有它，「拷贝」和「继续训练」就要抢同一块显存，异步又变回同步。</span></p><p><span class="marginnote">异步写尚未完成时又触发下一次保存，会堆积或覆盖。策略应是「进行中则跳过」或有界队列，并在日志里记实际成功的 step 号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在 step 边界：对参数与优化器状态做一次性一致捕获（可与 DP 分片、TP 分片、EP 分片的本地部分一起捕获，不必 gather 成整模型）。后台写本地分片。训练继续。故障恢复时，用下一课将定义的分布式格式按当前拓扑加载。保存频率按「丢失预算 / 平均步时」设：例如最多丢 15 分钟墙钟。</p><p>与数据加载器对齐：快照里必须有数据游标（样本 id、shuffle 种子、累积进度），否则恢复后会复读或跳过，污染去重会计。退火段切换 \\(w\\) 时，游标格式要能表达配比版本。</p><h3 id="校验" tabindex="-1">校验 <a class="header-anchor" href="#校验" aria-label="Permalink to &quot;校验&quot;">​</a></h3><p>后台写完后做校验和或抽检张量范数，失败则标红并保留上一个完好点。不要让损坏文件覆盖完好文件。原子 rename 是最低要求。</p><p><span class="marginnote">数字实例：丢失预算 15 分钟、平均步时 0.5 秒，就大约每 \\(15\\times 60\\div 0.5=1800\\) 步保存一次。异步保存的关键不是「存得多频繁」，而是这一次保存花多久都不阻塞训练——前提是拷贝没走同步 memcpy。</span></p><p><span class="marginnote">MoE 专家分片漏写一个 rank，恢复后会静默变成随机专家。完成标志必须是全局 AND，不是「大多数 rank 成功」。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>训练的关键路径只做一次设备内快照，IO 与后续 GEMM 并发。墙上保存开销趋向拷贝时间而不是文件系统尾延迟。正确性来自「快照点 = 优化器状态与数据游标的同一全局步」。这与零气泡的 step 必须在所有 \\(W\\) 之后，是同一条一致性链。</p>',20)),(t(),r(s,null,{default:l(()=>[i(n,{id:"mermaid-58",class:"mermaid",graph:"flowchart%20TD%0A%20%20ST%5B%22step%20%E8%BE%B9%E7%95%8C%E4%B8%80%E8%87%B4%E7%8A%B6%E6%80%81%22%5D%20--%3E%20SNAP%5B%22%E8%AE%BE%E5%A4%87%E4%BE%A7%E5%BF%AB%E7%85%A7%20%2F%20%E5%8F%8C%E7%BC%93%E5%86%B2%22%5D%0A%20%20SNAP%20--%3E%20TR%5B%22%E8%AE%AD%E7%BB%83%E7%BB%A7%E7%BB%AD%22%5D%0A%20%20SNAP%20--%3E%20WR%5B%22%E5%90%8E%E5%8F%B0%E5%86%99%E5%88%86%E7%89%87%22%5D%0A%20%20WR%20--%3E%20ATOM%5B%22%E5%8E%9F%E5%AD%90%E5%8F%91%E5%B8%83%E5%AE%8C%E6%88%90%E6%A0%87%E5%BF%97%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"边界",tabindex:"-1"},[E("边界 "),e("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[4]||(a[4]=e("p",null,"异步不保证故障时「正在写的那份」可用，因此始终要保留上一完好点。它也不定义分片如何在改 TP 度后读回来。下一课专门规定分布式检查点格式。弹性扩容时，未完成的 writer 必须取消或排空，否则旧世界的分片会与新世界混写。",-1)),(t(),r(s,null,{default:l(()=>[i(n,{id:"mermaid-65",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22step%20N%2B37%20%E8%AE%AD%E7%BB%83%E6%95%85%E9%9A%9C%22%5D%20--%3E%20A%5B%22%E4%B8%A2%E5%BC%83%E5%B0%9A%E6%9C%AA%E5%AE%8C%E6%88%90%E7%9A%84%E5%BC%82%E6%AD%A5%E5%86%99%22%5D%0A%20%20A%20--%3E%20B%5B%22%E6%89%BE%E6%9C%80%E8%BF%91%E4%B8%80%E4%B8%AA%E5%85%A8%E5%B1%80%20AND%20%E5%AE%8C%E6%88%90%E7%82%B9%EF%BC%9Astep%20N%22%5D%0A%20%20B%20--%3E%20C%5B%22%E6%8C%89%E5%BD%93%E5%89%8D%E6%8B%93%E6%89%91%E5%8A%A0%E8%BD%BD%E5%88%86%E7%89%87%5Cn%E5%8F%82%E6%95%B0%20%2B%20%E4%BC%98%E5%8C%96%E5%99%A8%20%2B%20%E6%95%B0%E6%8D%AE%E6%B8%B8%E6%A0%87%22%5D%0A%20%20C%20--%3E%20D%5B%22%E4%BB%8E%E6%B8%B8%E6%A0%87%E7%BB%AD%E8%AF%BB%E6%95%B0%E6%8D%AE%EF%BC%8C%E5%9B%9E%E5%88%B0%20step%20N%2B1%22%5D%0A%20%20D%20--%3E%20E%5B%22%E5%AE%9E%E9%99%85%E6%8D%9F%E5%A4%B1%20%3D%20N%2B1%20%E5%88%B0%20N%2B37%20%E7%9A%84%E5%A2%99%E9%92%9F%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=e("h2",{id:"小结",tabindex:"-1"},[E("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[6]||(a[6]=e("ul",null,[e("li",null,"本课不重讲 All-to-All；只补在 step 边界把保存移出关键路径。"),e("li",null,"快照必须含参数、优化器、数据游标；全局完成标志用 AND。"),e("li",null,"频率按丢失预算设；进行中的保存不可无界堆积。"),e("li",null,"DualPipe / ZB 的半拍不是合法快照点。"),e("li",null,[E("出处：Mohan et al., "),e("em",null,"CheckFreq"),E(", OSDI 2021；对照大规模训练中的异步保存实践。")])],-1))])}const k=o(d,[["render",m]]);export{f as __pageData,k as default};
